'use strict';
let enchantSelection=null,enchantMessage='';
function openEnchantWindow(){
 if(screen!=='play')return;ensureEnchantStarter();if(!$('characterOverlay').hidden)closeCharacterWindow();controlWindow='enchant';
 const body=document.createElement('div');body.className='enchant-panel';const list=document.createElement('div');list.className='enchant-items';list.setAttribute('aria-label','อุปกรณ์สำหรับตีบวก');
 if(!player.loot.gear.some(g=>g.id===enchantSelection))enchantSelection=player.loot.equipped.main||player.loot.gear[0]?.id||null;
 for(const gear of player.loot.gear){const button=document.createElement('button');button.className='enchant-item';button.classList.toggle('selected',gear.id===enchantSelection);button.dataset.gearId=gear.id;const icon=document.createElement('span');icon.innerHTML=gearIcon(gear);const name=document.createElement('span');name.textContent=gearDisplayName(gear);const detail=document.createElement('small');detail.textContent='Lv.'+gear.level+' · '+(Object.values(player.loot.equipped).includes(gear.id)?'สวมอยู่':'ในกระเป๋า');name.append(detail);button.append(icon,name);button.onclick=()=>{enchantSelection=gear.id;enchantMessage='';openEnchantWindow()};list.append(button)}
 const details=document.createElement('section');details.className='enchant-details';const gear=player.loot.gear.find(g=>g.id===enchantSelection);
 if(gear){const target=enchantLevel(gear)+1,maxed=target>ENCHANT_MAX,title=document.createElement('h3');title.textContent=gearDisplayName(gear);details.append(title);const step=document.createElement('strong');step.id='enchantStep';step.textContent=maxed?'+20 · สูงสุดแล้ว':'+'+enchantLevel(gear)+' → +'+target;details.append(step);
 const rates=document.createElement('p');rates.textContent='โอกาสสำเร็จ: '+(maxed?'—':enchantChance(target)+'%');rates.id='enchantChance';details.append(rates);const price=document.createElement('p');price.id='enchantCost';price.textContent='ค่าใช้จ่าย: '+(maxed?'—':enchantCost(gear).toLocaleString()+' เงิน');details.append(price);const wallet=document.createElement('p');wallet.id='enchantMoney';wallet.textContent='เงินที่มี: '+player.loot.money.toLocaleString();details.append(wallet);
 const formula=document.createElement('small');formula.textContent='ราคา = Lv.อุปกรณ์ × ขั้นบวกเป้าหมาย × 1,000';details.append(formula);
 const current=enchantedGear(gear),next=enchantedGear(gear,Math.min(ENCHANT_MAX,target)),stats=document.createElement('div');stats.className='enchant-preview';for(const key of ['atk','def','hp','mp'])if(current[key]||next[key]){const row=document.createElement('div');row.textContent=key.toUpperCase()+': '+current[key]+(maxed?'':' → '+next[key]);stats.append(row)}for(let i=0;i<current.bonuses.length;i++){const row=document.createElement('div');row.textContent=BONUS_NAMES[current.bonuses[i].key]+': '+current.bonuses[i].value+(maxed?'':' → '+next.bonuses[i].value);stats.append(row)}if(!stats.children.length)stats.textContent='ชิ้นนี้ไม่มีค่าสถานะพื้นฐานหรือออปชันให้เพิ่ม';details.append(stats);
 const rules=document.createElement('p');rules.className='enchant-rules';rules.textContent='เพิ่มค่าสถานะและออปชัน 5% ต่อขั้น · ไม่สำเร็จเสียเฉพาะเงิน ระดับเดิมคงอยู่ ของไม่หาย';details.append(rules);const result=document.createElement('p');result.id='enchantResult';result.setAttribute('role','status');result.textContent=enchantMessage;details.append(result);
 const button=document.createElement('button');button.id='enchantConfirm';button.className='primary';button.textContent=maxed?'ตีบวกเต็มแล้ว':'ตีบวก +'+target;button.disabled=maxed||player.loot.money<enchantCost(gear)||storageReadOnly;button.onclick=()=>{const outcome=attemptEnchant(gear.id);enchantMessage=!outcome.ok?outcome.reason:outcome.success?'สำเร็จ · '+gearDisplayName(gear):'ไม่สำเร็จ · คงระดับ +'+outcome.level+' · เสีย '+outcome.cost.toLocaleString()+' เงิน';openEnchantWindow()};details.append(button);
 }else details.textContent='ยังไม่มีอุปกรณ์';body.append(list,details);modal('Enchant · ตีบวกอุปกรณ์',body,[]);$('modal').classList.add('enchant-modal');$('modal').querySelector('.dialog-card').scrollTop=0;$('modalCloseBtn').focus({preventScroll:true});
}
for(const id of ['enchantMenuBtn','mobileEnchantBtn']){const button=$(id);button.disabled=false;button.removeAttribute('title');const label=button.querySelector('small');if(label)label.textContent='[F]';button.onclick=openEnchantWindow}
const beforeEnchantWindow=openControlWindow;openControlWindow=function(kind){if(kind==='enchant'){if(controlWindow==='enchant'&&$('modal').classList.contains('enchant-modal')&&!$('modal').hidden){closeModal();return}return openEnchantWindow()}return beforeEnchantWindow(kind)};
WINDOW_KEYS.KeyF='enchant';
const beforeEnchantSettings=openSettings;openSettings=function(){beforeEnchantSettings();for(const term of $('modalBody').querySelectorAll('dt'))if(term.textContent==='Party / Enchant'){term.textContent='Party';term.nextElementSibling.textContent='ยังไม่เปิดใช้งาน'}const dl=$('modalBody').querySelector('dl');if(dl){const term=document.createElement('dt'),definition=document.createElement('dd');term.textContent='Enchant';definition.textContent='F · ตีบวกอุปกรณ์ถึง +20';dl.append(term,definition)}};document.querySelectorAll('[data-settings]').forEach(button=>button.onclick=openSettings);
// DOMContentLoaded also assigns menu callbacks; route its Enchant callback through the wrapper above.

const beforeEnchantDescription=gearDescription;gearDescription=function(g){return beforeEnchantDescription(enchantedGear(g))+'\nตีบวก +'+enchantLevel(g)};
